@Component("serviceProvider-handler")
@ProcessingGroup("serviceProvider-processing-group")
public class ServiceProviderEventHandler {
	
	// core constructor
	ServiceProviderEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateServiceProviderEvent
     */
    @EventHandler
    public void handle( CreateServiceProviderEvent event) {
        entityManager.persist(new ServiceProvider(event.getServiceProviderId(), event.getName(), event.getTaxId(), event.getClaims(), event.getProviderType(), event.getNetworkStatus()));
    }

    /*
     * @param	event UpdateServiceProviderEvent
     */
    @EventHandler
    public ServiceProvider handle( UpdateServiceProviderEvent event) {
    	entityManager.merge(new ServiceProvider(event.getServiceProviderId(), event.getName(), event.getTaxId(), event.getClaims(), event.getProviderType(), event.getNetworkStatus()));
    }
    
    /*
     * @param	event DeleteServiceProviderEvent
     */
    @EventHandler
    public void on( DeleteServiceProviderEvent event) {
    	ServiceProvider entity = new ServiceProvider();
   
    	// ------------------------------------------
    	// apply the ServiceProviderId
    	// ------------------------------------------
    	entity.setServiceProviderId( event.getServiceProviderId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final ServiceProviderRepository serviceProviderEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(ServiceProviderEventHandler.class.getName());

}
